public class Main {
    static int maximum(int[] t) {
        int max = t[0];
        for (int v : t) {
            if (v > max) {
                max = v;
            }
        }
        return max;
    }

    static int joursAuDessus(int[] t, int seuil) {
        int compte = 0;
        for (int v : t) {
            if (v > seuil) {
                compte++;
            }
        }
        return compte;
    }

    public static void main(String[] args) {
        int[] ventes = {120, 340, 90, 410, 200};
        System.out.println("Record : " + maximum(ventes));
        System.out.println("Bons jours : " + joursAuDessus(ventes, 150));
    }
}

