import java.util.Scanner;

public class Main {
    static int minimum(int[] t) {
        int min = t[0];
        for (int v : t) {
            if (v < min) {
                min = v;
            }
        }
        return min;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine());
        int[] temp = new int[n];
        for (int i = 0; i < n; i++) {
            temp[i] = Integer.parseInt(sc.nextLine());
        }
        int max = temp[0];
        int total = 0;
        int chauds = 0;
        for (int v : temp) {
            if (v > max) max = v;
            total += v;
            if (v >= 35) chauds++;
        }
        System.out.println("Max : " + max);
        System.out.println("Min : " + minimum(temp));
        System.out.println("Moyenne : " + String.format("%.1f", (double) total / n));
        System.out.println("Jours chauds : " + chauds);
    }
}
